"use client"

import { useState } from "react"
import { useRouter, useParams } from "next/navigation"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { toast } from "sonner"
import { ChevronLeft, Upload, Loader2, Check, AlertCircle } from "lucide-react"
import Link from "next/link"
import { importProducts } from "../actions"
import Papa from "papaparse"
import * as XLSX from "xlsx"

export default function ProductImportPage() {
    const router = useRouter()
    const { slug } = useParams() as { slug: string }
    const [file, setFile] = useState<File | null>(null)
    const [preview, setPreview] = useState<any[]>([])
    const [isParsing, setIsParsing] = useState(false)
    const [isImporting, setIsImporting] = useState(false)
    const [result, setResult] = useState<{
        imported: number,
        skippedDuplicate: number,
        skippedInvalidData: number
    } | null>(null)

    const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const selectedFile = e.target.files?.[0]
        if (!selectedFile) return

        const isCSV = selectedFile.name.endsWith('.csv')
        const isExcel = selectedFile.name.endsWith('.xlsx') || selectedFile.name.endsWith('.xls')

        if (!isCSV && !isExcel) {
            toast.error("Please upload a CSV or Excel file (.csv, .xlsx, .xls)")
            return
        }

        setFile(selectedFile)
        setPreview([])
        setIsParsing(true)
        setResult(null)

        try {
            if (isCSV) {
                Papa.parse(selectedFile, {
                    header: true,
                    skipEmptyLines: true,
                    transformHeader: (header) => header.trim().toLowerCase(),
                    complete: function (results) {
                        processParsedData(results.data, results.meta.fields || [])
                    },
                    error: function (error: any) {
                        toast.error("Failed to parse CSV: " + error.message)
                        setIsParsing(false)
                    }
                })
            } else {
                const reader = new FileReader()
                reader.onload = (evt) => {
                    const bstr = evt.target?.result
                    const wb = XLSX.read(bstr, { type: 'binary' })
                    const wsname = wb.SheetNames[0]
                    const ws = wb.Sheets[wsname]
                    const data = XLSX.utils.sheet_to_json(ws, { header: 1 }) as any[]

                    if (data.length === 0) {
                        toast.error("Excel file is empty")
                        setIsParsing(false)
                        return
                    }

                    const rawHeaders = data[0] as string[]
                    const headers = rawHeaders.map(h => String(h || "").trim().toLowerCase())
                    const rows = data.slice(1)
                        .filter((row: any[]) => row && row.length > 0 && row.some(cell => cell !== undefined && cell !== null && String(cell).trim() !== ""))
                        .map((row: any[]) => {
                            const obj: any = {}
                            headers.forEach((header, index) => {
                                obj[header] = row[index]
                            })
                            return obj
                        })

                    processParsedData(rows, headers)
                }
                reader.onerror = () => {
                    toast.error("Failed to read Excel file")
                    setIsParsing(false)
                }
                reader.readAsBinaryString(selectedFile)
            }
        } catch (err) {
            toast.error("Parsing failed")
            setIsParsing(false)
        }
    }

    const processParsedData = (data: any[], headers: string[]) => {
        const REQUIRED_HEADERS = ['name', 'category', 'price', 'stock']
        const missingHeaders = REQUIRED_HEADERS.filter(h => !headers.includes(h))

        if (missingHeaders.length > 0) {
            toast.error(`Missing required headers: ${missingHeaders.join(', ')}`)
            setPreview([])
            setIsParsing(false)
            return
        }

        if (data.length > 1000) {
            toast.error("Maximum 1000 rows allowed")
            setPreview([])
        } else {
            setPreview(data)
        }
        setIsParsing(false)
    }

    const handleImport = async () => {
        if (!preview.length) return

        setIsImporting(true)
        try {
            const res = await importProducts(preview)
            if (res.error) {
                toast.error(res.error)
            } else {
                setResult({
                    imported: res.imported || 0,
                    skippedDuplicate: res.skippedDuplicate || 0,
                    skippedInvalidData: res.skippedInvalidData || 0
                })
                toast.success("Import completed")
            }
        } catch (error) {
            toast.error("Import failed")
        } finally {
            setIsImporting(false)
        }
    }

    return (
        <div className="container mx-auto p-4 md:p-8 max-w-4xl">
            <div className="flex items-center gap-4 mb-8">
                <Link href={`/${slug}/products`}>
                    <Button variant="ghost" size="icon">
                        <ChevronLeft className="h-4 w-4" />
                    </Button>
                </Link>
                <h1 className="text-3xl font-bold">Import Products</h1>
            </div>

            <Card className="mb-8 border-amber-200 bg-amber-50/30">
                <CardHeader>
                    <div className="flex items-center gap-2 text-amber-800">
                        <AlertCircle className="h-5 w-5" />
                        <CardTitle className="text-lg">IMPORTANT: CSV/Excel Format Requirement</CardTitle>
                    </div>
                </CardHeader>
                <CardContent className="text-amber-900">
                    <p className="mb-2">Your Excel/CSV file <strong>MUST</strong> have these exact column headers:</p>
                    <div className="flex flex-wrap gap-2 text-xs font-mono">
                        {['name', 'category', 'price', 'stock'].map(col => (
                            <span key={col} className="bg-white border border-amber-200 px-2 py-1 rounded">
                                {col}
                            </span>
                        ))}
                        <span className="bg-white border border-slate-200 px-2 py-1 rounded text-slate-500">
                            purchaseprice (optional)
                        </span>
                        <span className="bg-white border border-slate-200 px-2 py-1 rounded text-slate-500">
                            lowstockalert (optional)
                        </span>
                    </div>
                    <p className="mt-4 text-sm font-medium">Note: Category should be one of "PROTEIN", "SUPPLEMENT", "MERCHANDISE", or "OTHER" (or leave blank for OTHER).</p>
                </CardContent>
            </Card>

            <Card className="mb-8">
                <CardHeader>
                    <CardTitle>Step 1: Upload File</CardTitle>
                    <CardDescription>
                        Select your products list CSV or Excel file (max 1000 rows).
                    </CardDescription>
                </CardHeader>
                <CardContent>
                    <div className="grid w-full items-center gap-4">
                        <div className="flex flex-col space-y-1.5">
                            <Label htmlFor="product-file">Choose CSV or Excel File</Label>
                            <Input id="product-file" type="file" accept=".csv, .xlsx, .xls" onChange={handleFileChange} disabled={isImporting} />
                        </div>
                    </div>
                </CardContent>
            </Card>

            {preview.length > 0 && !result && (
                <Card className="mb-8">
                    <CardHeader>
                        <CardTitle>Step 2: Preview & Confirm</CardTitle>
                        <CardDescription>
                            Showing first 5 rows of {preview.length} products found.
                        </CardDescription>
                    </CardHeader>
                    <CardContent>
                        <div className="overflow-x-auto border rounded-md mb-6">
                            <table className="w-full text-sm text-left">
                                <thead className="bg-slate-50 border-b">
                                    <tr>
                                        <th className="px-4 py-2">Name</th>
                                        <th className="px-4 py-2">Category</th>
                                        <th className="px-4 py-2">Price</th>
                                        <th className="px-4 py-2">Stock</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {preview.slice(0, 5).map((row, i) => (
                                        <tr key={i} className="border-b last:border-0 font-medium">
                                            <td className="px-4 py-2">{row.name}</td>
                                            <td className="px-4 py-2">{row.category || "OTHER"}</td>
                                            <td className="px-4 py-2">₹{row.price}</td>
                                            <td className="px-4 py-2">{row.stock}</td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                        <Button onClick={handleImport} disabled={isImporting} className="w-full h-12 text-lg">
                            {isImporting ? (
                                <>
                                    <Loader2 className="mr-2 h-5 w-5 animate-spin" />
                                    Importing {preview.length} products...
                                </>
                            ) : (
                                <>
                                    <Check className="mr-2 h-5 w-5" />
                                    Confirm Import
                                </>
                            )}
                        </Button>
                    </CardContent>
                </Card>
            )}

            {result && (
                <Card className="border-blue-200 bg-blue-50/30">
                    <CardHeader>
                        <CardTitle className="text-blue-900 flex items-center">
                            <Check className="mr-2 h-6 w-6 text-green-600" />
                            Import Results
                        </CardTitle>
                    </CardHeader>
                    <CardContent>
                        <div className="space-y-2 text-sm text-blue-900">
                            <p><strong>{result.imported}</strong> products successfully imported.</p>
                            {result.skippedDuplicate > 0 && <p className="text-amber-700"><strong>{result.skippedDuplicate}</strong> skipped (duplicate name).</p>}
                            {result.skippedInvalidData > 0 && <p className="text-red-600"><strong>{result.skippedInvalidData}</strong> skipped (invalid data).</p>}
                        </div>
                        <Button className="mt-6" variant="outline" onClick={() => {
                            setResult(null);
                            setPreview([]);
                            setFile(null);
                            const input = document.getElementById('product-file') as HTMLInputElement;
                            if (input) input.value = '';
                        }}>Upload Another File</Button>
                    </CardContent>
                </Card>
            )}
        </div>
    )
}

"use client"

import { useState, useEffect, useRef } from "react"
import { CheckCircle2, Loader2, Phone, Zap, ArrowRight, RotateCcw, Clock, Delete } from "lucide-react"
import { useParams } from "next/navigation"
import { motion, AnimatePresence } from "framer-motion"

type CheckInState = "idle" | "loading" | "success" | "error"

const STORAGE_KEY_PREFIX = "gm_checkin_phone_"

export default function CheckInPage() {
    const params = useParams()
    const slug = Array.isArray(params.slug) ? params.slug[0] : params.slug || ""

    const [phone, setPhone] = useState("")
    const [savedPhone, setSavedPhone] = useState<string | null>(null)
    const [gymName, setGymName] = useState("")
    const [state, setState] = useState<CheckInState>("idle")
    const [message, setMessage] = useState("")
    const [memberName, setMemberName] = useState("")
    const [isReturningMember, setIsReturningMember] = useState(false)
    const [time, setTime] = useState(new Date())
    const inputRef = useRef<HTMLInputElement>(null)
    const storageKey = `${STORAGE_KEY_PREFIX}${slug}`

    // Clock effect
    useEffect(() => {
        const timer = setInterval(() => setTime(new Date()), 1000)
        return () => clearInterval(timer)
    }, [])

    useEffect(() => {
        // Load gym info
        fetch(`/api/public/${slug}/checkin`)
            .then(r => r.json())
            .then(data => {
                if (data.gymName) setGymName(data.gymName)
            })
            .catch(() => { })

        try {
            const remembered = localStorage.getItem(storageKey)
            if (remembered) {
                setSavedPhone(remembered)
                setPhone(remembered)
                setIsReturningMember(true)
            }
        } catch (e) {
            console.error("localStorage access failed:", e)
        }
    }, [slug, storageKey])

    const handleCheckIn = async (phoneNum: string) => {
        if (phoneNum.length < 10) return
        setState("loading")
        setMessage("")

        try {
            const res = await fetch(`/api/public/${slug}/checkin`, {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ phone: phoneNum.trim() }),
            })
            const data = await res.json()

            if (!res.ok) {
                setState("error")
                setMessage(data.error || "Something went wrong.")
                setTimeout(() => {
                    setState("idle")
                    setPhone("")
                }, 3000)
                return
            }

            try {
                localStorage.setItem(storageKey, phoneNum.trim())
            } catch (e) {
                console.error("localStorage access failed:", e)
            }
            setSavedPhone(phoneNum.trim())
            setIsReturningMember(true)
            setMemberName(data.memberName || "")
            setState("success")

            // Clear phone input for next time
            setPhone("")

            setTimeout(() => {
                setState("idle")
                setMessage("")
            }, 5000)
        } catch {
            setState("error")
            setMessage("Network error.")
            setTimeout(() => setState("idle"), 3000)
        }
    }

    const appendDigit = (digit: string) => {
        if (phone.length < 10) setPhone(prev => prev + digit)
    }

    const backspace = () => {
        setPhone(prev => prev.slice(0, -1))
    }

    const KeypadButton = ({ value, onClick, className = "" }: { value: string | React.ReactNode, onClick: () => void, className?: string }) => (
        <button
            onClick={onClick}
            className={`h-20 w-20 rounded-full flex items-center justify-center text-2xl font-bold transition-all active:scale-95 active:bg-white/20 select-none ${className}`}
            style={{ background: "rgba(255,255,255,0.05)", border: "1px solid rgba(255,255,255,0.1)" }}
        >
            {value}
        </button>
    )

    return (
        <div className="min-h-screen bg-[#050510] text-white flex flex-col items-center justify-between p-6 md:p-12 overflow-hidden relative">
            {/* Background elements */}
            <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-sky-500/10 blur-[120px] rounded-full" />
            <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-indigo-500/10 blur-[120px] rounded-full" />

            {/* Top Bar: Time and Gym Name */}
            <header className="w-full flex items-center justify-between relative z-20">
                <div className="flex flex-col">
                    <h1 className="text-2xl md:text-3xl font-black tracking-tighter uppercase">{gymName || "GymMitra"}</h1>
                    <div className="flex items-center gap-2 text-sky-400 font-bold text-xs tracking-widest uppercase mt-1">
                        <span className="h-1.5 w-1.5 rounded-full bg-sky-400 animate-pulse" />
                        Kiosk Mode Active
                    </div>
                </div>
                <div className="text-right">
                    <div className="text-3xl md:text-5xl font-black tracking-tighter flex items-center justify-end gap-3">
                        <Clock className="h-6 w-6 md:h-8 md:w-8 text-slate-500" />
                        {time.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                    </div>
                    <div className="text-slate-500 text-sm font-bold uppercase tracking-widest mt-1">
                        {time.toLocaleDateString([], { weekday: 'long', day: 'numeric', month: 'short' })}
                    </div>
                </div>
            </header>

            {/* Main Center Area */}
            <main className="flex-1 w-full max-w-7xl flex flex-col md:flex-row items-center justify-center gap-12 md:gap-24 relative z-10">

                <AnimatePresence mode="wait">
                    {state === "success" ? (
                        <motion.div
                            key="success"
                            initial={{ opacity: 0, scale: 0.9, y: 20 }}
                            animate={{ opacity: 1, scale: 1, y: 0 }}
                            exit={{ opacity: 0, scale: 1.1 }}
                            className="flex flex-col items-center text-center space-y-8"
                        >
                            <div className="relative">
                                <div className="h-48 w-48 md:h-64 md:w-64 rounded-full bg-emerald-500/20 border-4 border-emerald-500/50 flex items-center justify-center shadow-[0_0_80px_rgba(16,185,129,0.3)]">
                                    <CheckCircle2 className="h-24 w-24 md:h-32 md:w-32 text-emerald-400" />
                                </div>
                                <motion.div
                                    initial={{ scale: 0 }}
                                    animate={{ scale: 1 }}
                                    transition={{ delay: 0.3, type: "spring" }}
                                    className="absolute -bottom-4 left-1/2 -translate-x-1/2 bg-white text-emerald-600 font-black px-6 py-2 rounded-full shadow-xl"
                                >
                                    SUCCESS
                                </motion.div>
                            </div>

                            <div className="space-y-2">
                                <h2 className="text-4xl md:text-6xl font-black text-white">
                                    {memberName ? `Welcome, ${memberName.split(' ')[0]}!` : "Welcome In!"}
                                </h2>
                                <p className="text-emerald-400 md:text-2xl font-bold tracking-tight">Consistency is the key to success. 💪</p>
                            </div>

                            <div className="w-full max-w-xs h-1.5 bg-white/10 rounded-full overflow-hidden mt-8">
                                <motion.div
                                    initial={{ width: "100%" }}
                                    animate={{ width: "0%" }}
                                    transition={{ duration: 5, ease: "linear" }}
                                    className="h-full bg-emerald-400"
                                />
                            </div>
                            <p className="text-slate-500 text-xs font-bold uppercase tracking-widest">Resetting in 5 seconds</p>
                        </motion.div>
                    ) : (
                        <motion.div
                            key="kiosk"
                            initial={{ opacity: 0, x: -20 }}
                            animate={{ opacity: 1, x: 0 }}
                            exit={{ opacity: 0, x: 20 }}
                            className="w-full flex flex-col md:flex-row items-center justify-center gap-12 md:gap-24"
                        >
                            {/* Left: Branding & Message */}
                            <div className="hidden md:flex flex-col space-y-6 max-w-md">
                                <div className="h-16 w-16 bg-white/5 rounded-2xl flex items-center justify-center border border-white/10">
                                    <Zap className="h-8 w-8 text-sky-400" />
                                </div>
                                <h2 className="text-6xl font-black leading-none tracking-tighter uppercase font-serif">
                                    Ready to <br />
                                    <span className="text-sky-400">Transform?</span>
                                </h2>
                                <p className="text-xl text-slate-400 font-medium">Enter your 10-digit registered phone number to check in.</p>
                                <div className="flex gap-4">
                                    <div className="bg-white/5 border border-white/10 p-4 rounded-2xl flex-1">
                                        <p className="text-xs text-slate-500 font-bold uppercase mb-1">Status</p>
                                        <div className="flex items-center gap-2">
                                            <div className="h-2 w-2 rounded-full bg-emerald-400 animate-pulse" />
                                            <p className="text-lg font-black uppercase text-emerald-400">Live</p>
                                        </div>
                                    </div>
                                    <div className="bg-white/5 border border-white/10 p-4 rounded-2xl flex-1">
                                        <p className="text-xs text-slate-500 font-bold uppercase mb-1">Secure</p>
                                        <p className="text-lg font-black text-slate-300 uppercase">Encrypted</p>
                                    </div>
                                </div>
                            </div>

                            {/* Right: Phone Input & Keypad */}
                            <div className="w-full max-w-sm space-y-8">
                                <div className="relative group">
                                    <div className="absolute inset-0 bg-sky-500/10 blur-[40px] group-focus-within:bg-sky-500/20 transition-all rounded-full" />
                                    <div className="relative">
                                        <div className="text-center md:hidden mb-6">
                                            <p className="text-slate-400 font-bold uppercase tracking-widest text-xs">Enter Member Phone</p>
                                        </div>
                                        <div className="flex items-center justify-center gap-3 bg-white/[0.03] border border-white/10 group-focus-within:border-sky-500/50 p-6 rounded-3xl backdrop-blur-xl shadow-2xl transition-all h-24">
                                            <Phone className="h-6 w-6 text-slate-500" />
                                            <div className="flex-1 text-4xl md:text-5xl font-black tracking-[0.2em] text-center font-mono">
                                                {phone.padEnd(10, "·").split("").map((char, i) => (
                                                    <span key={i} className={char === "·" ? "text-white/10" : "text-white"}>
                                                        {char}
                                                    </span>
                                                ))}
                                            </div>
                                        </div>
                                    </div>
                                </div>

                                {state === "error" && (
                                    <motion.div
                                        initial={{ opacity: 0, y: -10 }}
                                        animate={{ opacity: 1, y: 0 }}
                                        className="bg-rose-500/10 border border-rose-500/20 p-4 rounded-2xl text-center"
                                    >
                                        <p className="text-rose-400 font-bold uppercase text-xs tracking-widest">{message}</p>
                                    </motion.div>
                                )}

                                {/* Numeric Keypad */}
                                <div className="grid grid-cols-3 gap-4 place-items-center">
                                    {["1", "2", "3", "4", "5", "6", "7", "8", "9"].map(num => (
                                        <KeypadButton key={num} value={num} onClick={() => appendDigit(num)} />
                                    ))}
                                    <KeypadButton
                                        value={<RotateCcw className="h-8 w-8 text-slate-500" />}
                                        onClick={() => setPhone("")}
                                        className="bg-white/0 border-none"
                                    />
                                    <KeypadButton value="0" onClick={() => appendDigit("0")} />
                                    <KeypadButton
                                        value={<Delete className="h-8 w-8 text-slate-500" />}
                                        onClick={backspace}
                                        className="bg-white/0 border-none"
                                    />
                                </div>

                                <button
                                    onClick={() => handleCheckIn(phone)}
                                    disabled={phone.length < 10 || state === "loading"}
                                    className="w-full h-20 rounded-3xl font-black text-2xl text-white transition-all duration-300 flex items-center justify-center gap-4 disabled:opacity-20 relative overflow-hidden group shadow-[0_0_24px_rgba(14,165,233,0.2)]"
                                    style={{
                                        background: state === "loading"
                                            ? "rgba(14,165,233,0.3)"
                                            : "linear-gradient(135deg, #0EA5E9 0%, #6366F1 100%)",
                                    }}
                                >
                                    {state === "loading" ? (
                                        <Loader2 className="h-8 w-8 animate-spin" />
                                    ) : (
                                        <>
                                            CHECK IN
                                            <ArrowRight className="h-6 w-6 group-hover:translate-x-2 transition-transform" />
                                        </>
                                    )}
                                </button>

                                {isReturningMember && savedPhone && phone !== savedPhone && (
                                    <button
                                        onClick={() => { setPhone(savedPhone); handleCheckIn(savedPhone); }}
                                        className="w-full text-center text-slate-500 hover:text-white font-bold text-sm uppercase tracking-widest pt-2 transition-colors"
                                    >
                                        Use previous: {savedPhone.slice(0, 3)}...{savedPhone.slice(-4)}
                                    </button>
                                )}
                            </div>
                        </motion.div>
                    )}
                </AnimatePresence>

            </main>

            {/* Bottom Footer */}
            <footer className="w-full flex items-center justify-between text-slate-700 font-bold text-[10px] md:text-xs uppercase tracking-[0.3em] relative z-20 pt-12">
                <div className="flex items-center gap-2">
                    <span className="text-slate-800">ENIP</span>
                    <span>0xFF293</span>
                </div>
                <div className="text-center hidden md:block">
                    POWERED BY GYMMITRA CORE • SECURE ACCESS SYSTEM
                </div>
                <div className="flex items-center gap-4">
                    <span>V4.2.0</span>
                    <span className="h-1 w-8 bg-slate-800 rounded-full" />
                </div>
            </footer>
        </div>
    )
}

'use client'

import React, { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import { motion, AnimatePresence } from 'framer-motion'
import { Card, CardContent } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { toast } from "sonner"
import { Building2, MapPin, Contact, CreditCard, CheckCircle2, ArrowRight, ArrowLeft, ImagePlus, X } from 'lucide-react'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import { completeOnboarding } from './actions'

const INDIAN_STATES = [
    "Andhra Pradesh", "Arunachal Pradesh", "Assam", "Bihar", "Chhattisgarh", "Goa", "Gujarat",
    "Haryana", "Himachal Pradesh", "Jharkhand", "Karnataka", "Kerala", "Madhya Pradesh", "Maharashtra",
    "Manipur", "Meghalaya", "Mizoram", "Nagaland", "Odisha", "Punjab", "Rajasthan", "Sikkim",
    "Tamil Nadu", "Telangana", "Tripura", "Uttar Pradesh", "Uttarakhand", "West Bengal",
    "Andaman and Nicobar Islands", "Chandigarh", "Dadra and Nagar Haveli and Daman and Diu",
    "Delhi", "Jammu and Kashmir", "Ladakh", "Lakshadweep", "Puducherry"
];

const steps = [
    { title: 'Business Info', icon: Building2 },
    { title: 'Location', icon: MapPin },
    { title: 'Contact', icon: Contact },
    { title: 'Membership Plans', icon: CheckCircle2 },
    { title: 'Invoice Setup', icon: CreditCard },
]

export default function OnboardingForm() {
    const router = useRouter()
    const [currentStep, setCurrentStep] = useState(0)
    const [isSubmitting, setIsSubmitting] = useState(false)
    const [states, setStates] = useState<string[]>(INDIAN_STATES)
    const [logoFile, setLogoFile] = useState<File | null>(null)
    const [logoPreview, setLogoPreview] = useState<string | null>(null)
    const [formData, setFormData] = useState({
        businessName: '',
        ownerName: '',
        email: '',
        address: '',
        city: '',
        state: '',
        pincode: '',
        phone: '',
        upiId: '',
        invoicePrefix: '',
        termsAndConditions: '1. Fees once paid are non-refundable.\n2. Management is not responsible for personal belongings.',
        gymRules: '1. Always wipe down equipment after use.\n2. Re-rack weights after finishing your set.\n3. Appropriate gym attire and closed-toe shoes are mandatory.',
        plans: [] as { name: string; durationMonths: number; price: number; enabled: boolean }[],
        futurePlanPreference: 'BASIC',
    })

    // Pre-fill from existing GymProfile (trial signup already saves gymName, ownerName, email, phone, city)
    useEffect(() => {
        const prefill = async () => {
            try {
                const res = await fetch('/api/settings')
                if (!res.ok) return
                const data = await res.json()
                setFormData(prev => ({
                    ...prev,
                    businessName: data.name || data.businessName || prev.businessName,
                    ownerName: data.ownerName || prev.ownerName,
                    email: data.email || prev.email,
                    phone: data.phone || prev.phone,
                    city: data.city || prev.city,
                    address: data.address || prev.address,
                }))
                if (data.logo) setLogoPreview(data.logo)
            } catch {
                // Silently fail — user can fill manually
            }
        }
        prefill()
    }, [])

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const { name, value } = e.target
        setFormData(prev => ({ ...prev, [name]: value }))
    }

    const addPlan = () => {
        setFormData(prev => ({
            ...prev,
            plans: [...prev.plans, { name: '', durationMonths: 1, price: 0, enabled: true }],
        }))
    }

    const removePlan = (index: number) => {
        setFormData(prev => ({
            ...prev,
            plans: prev.plans.filter((_, i) => i !== index),
        }))
    }

    const updatePlan = (index: number, field: 'name' | 'durationMonths', value: string | number) => {
        setFormData(prev => {
            const newPlans = [...prev.plans]
            newPlans[index] = { ...newPlans[index], [field]: value }
            return { ...prev, plans: newPlans }
        })
    }



    const handleLogoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0]
        if (file) {
            if (file.size > 2 * 1024 * 1024) {
                toast.error("Logo size must be less than 2MB")
                return
            }
            setLogoFile(file)
            const reader = new FileReader()
            reader.onloadend = () => {
                setLogoPreview(reader.result as string)
            }
            reader.readAsDataURL(file)
        }
    }

    const { pincode } = formData;
    useEffect(() => {
        const controller = new AbortController()

        const fetchPincodeDetails = async () => {
            if (pincode?.length === 6) {
                try {
                    const res = await fetch(`https://api.postalpincode.in/pincode/${pincode}`, { signal: controller.signal })
                    const data = await res.json()

                    if (data && data[0] && data[0].Status === 'Success') {
                        const postOffice = data[0].PostOffice[0]
                        const fetchedState = postOffice.State
                        const fetchedCity = postOffice.District

                        // If state does not exist in our current dropdown list or it is empty, add it 
                        setStates(prev => {
                            if (!prev.includes(fetchedState)) return [...prev, fetchedState].sort()
                            return prev
                        })

                        setFormData(prev => ({ ...prev, state: fetchedState, city: fetchedCity }))
                    } else {
                        toast.error("Invalid pincode or details not found.")
                    }
                } catch (error: any) {
                    if (error.name === 'AbortError') return
                    console.warn("Failed to fetch pincode details:", error)
                    // We don't want to show an intrusive toast or overlay if the third party API is down or adblocked.
                }
            }
        }

        const timeoutId = setTimeout(() => {
            fetchPincodeDetails()
        }, 500) // Debounce

        return () => {
            clearTimeout(timeoutId)
            controller.abort()
        }
    }, [pincode])

    const removeLogo = () => {
        setLogoFile(null)
        setLogoPreview(null)
    }

    const nextStep = () => {
        const form = document.querySelector('form')
        if (currentStep === 3 && formData.plans.length === 0) {
            toast.error("Please add at least one membership plan to continue.")
            return
        }
        if (currentStep === 3 && formData.plans.some(p => !p.name.trim())) {
            toast.error("Please give each plan a name.")
            return
        }
        if (form && form.reportValidity()) {
            setCurrentStep(prev => Math.min(prev + 1, steps.length - 1))
        }
    }
    const prevStep = () => setCurrentStep(prev => Math.max(prev - 1, 0))

    const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault()

        if (currentStep < steps.length - 1) {
            nextStep()
            return
        }

        setIsSubmitting(true)

        // 1. Call server action
        let result: { redirectTo?: string; warnings?: string[]; error?: string }
        try {
            const submissionData = new FormData()
            Object.entries(formData).forEach(([key, value]) => {
                if (key === 'plans') {
                    submissionData.append(key, JSON.stringify(value))
                } else {
                    submissionData.append(key, value as string)
                }
            })
            if (logoFile) {
                submissionData.append('logo', logoFile)
            }
            result = await completeOnboarding(submissionData)

            if (result.error) {
                toast.error(result.error)
                setIsSubmitting(false)
                return
            }
        } catch (error) {
            console.error("Onboarding failed:", error)
            toast.error(error instanceof Error ? error.message : "Something went wrong. Please check your inputs.")
            setIsSubmitting(false)
            return
        }

        // 2. Validate response and navigate
        if (!result.redirectTo) {
            toast.error("Onboarding saved, but we couldn't determine where to redirect. Please go to your dashboard manually.")
            setIsSubmitting(false)
            return
        }

        // Surface any non-fatal warnings (e.g. plan creation failed)
        if (result.warnings?.length) {
            result.warnings.forEach(w => toast.warning(w))
        }

        try {
            toast.success('Onboarding complete! Redirecting...')
            router.push(result.redirectTo)
        } catch (navError) {
            console.error("Navigation failed:", navError)
            toast.error("Your profile was saved but navigation failed. Please refresh or go to your dashboard.")
            setIsSubmitting(false)
        }
    }

    return (
        <div className="min-h-[80vh] flex items-center justify-center p-4">
            <Card className="w-full max-w-2xl overflow-hidden">
                <div className="bg-primary/5 p-6 border-b">
                    <div className="flex justify-between items-center mb-6 px-2">
                        {steps.map((step, idx) => {
                            const Icon = step.icon
                            const isActive = idx === currentStep
                            const isCompleted = idx < currentStep
                            return (
                                <div key={step.title} className="flex flex-col items-center gap-2 relative flex-1">
                                    <div className={`w-8 h-8 md:w-10 md:h-10 rounded-full flex items-center justify-center transition-colors duration-300 z-10 ${isActive ? 'bg-primary text-white scale-110 shadow-lg' :
                                        isCompleted ? 'bg-emerald-500 text-white' : 'bg-slate-200 text-slate-500'
                                        }`}>
                                        {isCompleted ? <CheckCircle2 className="w-5 h-5 md:w-6 md:h-6" /> : <Icon className="w-4 h-4 md:w-5 md:h-5" />}
                                    </div>
                                    <span className={`text-[9px] md:text-[10px] uppercase tracking-wider font-bold text-center hidden sm:block ${isActive ? 'text-primary' : 'text-slate-400'
                                        }`}>
                                        {step.title}
                                    </span>
                                    {idx < steps.length - 1 && (
                                        <div className={`absolute top-4 md:top-5 left-[50%] w-full h-[2px] -z-0 ${isCompleted ? 'bg-emerald-500' : 'bg-slate-200'
                                            }`} />
                                    )}
                                </div>
                            )
                        })}
                    </div>
                    {/* Current step label for mobile only */}
                    <div className="sm:hidden text-center">
                        <span className="text-xs font-black uppercase text-primary tracking-widest">
                            Step {currentStep + 1}: {steps[currentStep].title}
                        </span>
                    </div>
                </div>

                <form onSubmit={handleSubmit}>
                    <CardContent className="p-8">
                        <AnimatePresence mode="wait">
                            <motion.div
                                key={currentStep}
                                initial={{ opacity: 0, x: 20 }}
                                animate={{ opacity: 1, x: 0 }}
                                exit={{ opacity: 0, x: -20 }}
                                transition={{ duration: 0.2 }}
                                className="space-y-6"
                            >
                                {currentStep === 0 && (
                                    <div className="space-y-6">
                                        {/* Logo Upload Section */}
                                        <div className="space-y-3">
                                            <Label htmlFor="gymLogo" className="text-sm font-bold text-drift-700">Gym Logo (Optional)</Label>
                                            <div className="flex items-center gap-6">
                                                <div className="relative group">
                                                    <div className={`w-28 h-28 rounded-2xl border-2 border-dashed flex items-center justify-center overflow-hidden transition-all ${logoPreview ? 'border-ion-500 bg-white' : 'border-drift-200 bg-drift-50 hover:bg-drift-100 hover:border-ion-300'}`}>
                                                        {logoPreview ? (
                                                            <img src={logoPreview} alt="Logo Preview" className="w-full h-full object-contain" />
                                                        ) : (
                                                            <div className="flex flex-col items-center gap-1 text-drift-400">
                                                                <ImagePlus className="w-8 h-8" />
                                                                <span className="text-[10px] font-bold uppercase">Upload</span>
                                                            </div>
                                                        )}
                                                    </div>
                                                    {logoPreview && (
                                                        <button
                                                            onClick={removeLogo}
                                                            type="button"
                                                            className="absolute -top-2 -right-2 bg-rose-500 text-white rounded-full p-1 shadow-lg hover:bg-rose-600 transition-colors"
                                                        >
                                                            <X className="w-3 h-3" />
                                                        </button>
                                                    )}
                                                    <input
                                                        id="gymLogo"
                                                        type="file"
                                                        accept="image/*"
                                                        value=""
                                                        onChange={handleLogoChange}
                                                        className="absolute inset-0 opacity-0 cursor-pointer"
                                                        title="Upload Gym Logo"
                                                    />
                                                </div>
                                                <div className="flex-1 space-y-1">
                                                    <h4 className="text-sm font-bold text-drift-900">Brand Identity</h4>
                                                    <p className="text-xs text-drift-500 leading-relaxed font-medium">
                                                        Add your professional logo. This will be featured on member invoices and dashboard. Max 2MB.
                                                    </p>
                                                </div>
                                            </div>
                                        </div>

                                        <div className="space-y-4">
                                            <div className="space-y-2">
                                                <Label htmlFor="businessName">Gym/Business Name</Label>
                                                <Input
                                                    id="businessName"
                                                    name="businessName"
                                                    value={formData.businessName}
                                                    onChange={handleInputChange}
                                                    placeholder="e.g. Gym Name"
                                                    autoComplete="organization"
                                                    required
                                                />
                                                <p className="text-xs text-muted-foreground">This name will appear on all your invoices.</p>
                                            </div>
                                            <div className="space-y-2">
                                                <Label htmlFor="ownerName">Owner Name</Label>
                                                <Input
                                                    id="ownerName"
                                                    name="ownerName"
                                                    value={formData.ownerName}
                                                    onChange={handleInputChange}
                                                    placeholder="e.g. Nikhil Pal"
                                                    autoComplete="name"
                                                    required
                                                />
                                                <p className="text-xs text-muted-foreground">We&apos;ll use this name for personalized communication.</p>
                                            </div>
                                            <div className="space-y-2">
                                                <Label htmlFor="email">Public/Business Email</Label>
                                                <Input
                                                    id="email"
                                                    name="email"
                                                    type="email"
                                                    value={formData.email}
                                                    onChange={handleInputChange}
                                                    placeholder="contact@gymname.com"
                                                    autoComplete="email"
                                                    required
                                                />
                                            </div>
                                        </div>
                                    </div>
                                )}

                                {currentStep === 1 && (
                                    <div className="space-y-4">
                                        <div className="space-y-2">
                                            <Label htmlFor="address">Address (Street/Area)</Label>
                                            <Input
                                                id="address"
                                                name="address"
                                                value={formData.address}
                                                onChange={handleInputChange}
                                                placeholder="Street Address, Area"
                                                autoComplete="street-address"
                                                required
                                            />
                                        </div>
                                        <div className="grid grid-cols-2 gap-4">
                                            <div className="space-y-2">
                                                <Label htmlFor="city">City</Label>
                                                <Input
                                                    id="city"
                                                    name="city"
                                                    value={formData.city}
                                                    onChange={handleInputChange}
                                                    placeholder="City"
                                                    autoComplete="address-level2"
                                                    required
                                                />
                                            </div>
                                            <div className="space-y-2">
                                                <Label htmlFor="state">State</Label>
                                                <Select
                                                    value={formData.state}
                                                    onValueChange={(val) => setFormData(prev => ({ ...prev, state: val }))}
                                                >
                                                    <SelectTrigger id="state" className="bg-white px-3 py-2 border rounded-md shadow-sm">
                                                        <SelectValue placeholder="Select State" />
                                                    </SelectTrigger>
                                                    <SelectContent>
                                                        {states.map((s) => (
                                                            <SelectItem key={s} value={s}>{s}</SelectItem>
                                                        ))}
                                                    </SelectContent>
                                                </Select>
                                            </div>
                                        </div>
                                        <div className="space-y-2">
                                            <Label htmlFor="pincode">Pincode</Label>
                                            <Input
                                                id="pincode"
                                                name="pincode"
                                                value={formData.pincode}
                                                onChange={handleInputChange}
                                                placeholder="000000"
                                                autoComplete="postal-code"
                                                required
                                                type="text"
                                                inputMode="numeric"
                                                pattern="^[0-9]{6}$"
                                                maxLength={6}
                                                title="Please enter a valid 6-digit Indian PIN code"
                                                aria-invalid={!/^[0-9]{6}$/.test(formData.pincode) && formData.pincode.length > 0}
                                            />
                                        </div>
                                    </div>
                                )}

                                {currentStep === 2 && (
                                    <div className="space-y-4">
                                        <div className="space-y-2">
                                            <Label htmlFor="phone">Phone Number</Label>
                                            <Input
                                                id="phone"
                                                name="phone"
                                                value={formData.phone}
                                                onChange={handleInputChange}
                                                placeholder="9876543210"
                                                autoComplete="tel"
                                                required
                                                type="tel"
                                                inputMode="tel"
                                                pattern="^[0-9]{10}$"
                                                title="Please enter a valid 10-digit phone number"
                                            />
                                        </div>
                                        <div className="space-y-2">
                                            <Label htmlFor="upiId">UPI ID (for Payments)</Label>
                                            <Input
                                                id="upiId"
                                                name="upiId"
                                                value={formData.upiId}
                                                onChange={handleInputChange}
                                                placeholder="username@upi"
                                                required
                                            />
                                            <p className="text-xs text-muted-foreground">Used to generate QR codes on invoices.</p>
                                        </div>
                                    </div>
                                )}

                                {currentStep === 3 && (
                                    <div className="space-y-4">
                                        <div className="space-y-2 mb-4">
                                            <Label>Create your Membership Plans</Label>
                                            <p className="text-xs text-muted-foreground">Add the plans you offer to members. You can set the price later in Settings.</p>
                                        </div>

                                        {formData.plans.length === 0 && (
                                            <div className="text-center py-8 border-2 border-dashed border-slate-200 rounded-lg">
                                                <p className="text-sm text-muted-foreground mb-2">No plans added yet</p>
                                                <p className="text-xs text-muted-foreground">Click the button below to create your first plan</p>
                                            </div>
                                        )}

                                        <div className="grid gap-3">
                                            {formData.plans.map((plan, index) => (
                                                <div key={index} className="flex items-center gap-3 p-3 border rounded-lg border-slate-200 bg-white">
                                                    <div className="flex-1">
                                                        <Input
                                                            placeholder="Plan name (e.g. Monthly, Premium, Student)"
                                                            value={plan.name}
                                                            onChange={(e) => updatePlan(index, 'name', e.target.value)}
                                                            className="text-sm"
                                                        />
                                                    </div>
                                                    <div className="w-28">
                                                        <select
                                                            value={plan.durationMonths}
                                                            onChange={(e) => updatePlan(index, 'durationMonths', parseInt(e.target.value))}
                                                            className="flex h-10 w-full rounded-md border border-slate-200 bg-white px-3 py-2 text-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary"
                                                        >
                                                            <option value={1}>1 Month</option>
                                                            <option value={2}>2 Months</option>
                                                            <option value={3}>3 Months</option>
                                                            <option value={6}>6 Months</option>
                                                            <option value={12}>12 Months</option>
                                                        </select>
                                                    </div>
                                                    <button
                                                        type="button"
                                                        onClick={() => removePlan(index)}
                                                        className="p-2 text-slate-400 hover:text-red-500 transition-colors"
                                                        aria-label={`Remove ${plan.name || 'plan'}`}
                                                    >
                                                        <X className="w-4 h-4" />
                                                    </button>
                                                </div>
                                            ))}
                                        </div>

                                        <Button
                                            type="button"
                                            variant="outline"
                                            className="w-full border-dashed"
                                            onClick={addPlan}
                                        >
                                            <span className="mr-2">+</span> Add Plan
                                        </Button>
                                    </div>
                                )}

                                {currentStep === 4 && (
                                    <div className="space-y-4 text-center">
                                        <div className="space-y-2 text-left">
                                            <Label htmlFor="invoicePrefix">Invoice Prefix</Label>
                                            <Input
                                                id="invoicePrefix"
                                                name="invoicePrefix"
                                                value={formData.invoicePrefix}
                                                onChange={handleInputChange}
                                                placeholder="e.g. INV"
                                                maxLength={5}
                                                autoComplete="off"
                                                required
                                            />
                                            <p className="text-xs text-muted-foreground">Invoices will look like {formData.invoicePrefix || 'GM'}-INV-0001</p>
                                        </div>
                                        <div className="space-y-2 text-left mt-4">
                                            <Label htmlFor="termsAndConditions">Invoice Terms & Conditions (Billing Policies)</Label>
                                            <textarea
                                                id="termsAndConditions"
                                                name="termsAndConditions"
                                                className="flex min-h-[100px] w-full rounded-md border border-slate-200 bg-white px-3 py-2 text-sm ring-offset-white placeholder:text-slate-500 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
                                                value={formData.termsAndConditions}
                                                onChange={(e) => handleInputChange(e as any)}
                                                placeholder="Enter invoice terms here (e.g. Refund policy)..."
                                            />
                                        </div>
                                        <div className="space-y-2 text-left mt-4">
                                            <Label htmlFor="gymRules">Gym Rules (Member Guidelines)</Label>
                                            <textarea
                                                id="gymRules"
                                                name="gymRules"
                                                className="flex min-h-[100px] w-full rounded-md border border-slate-200 bg-white px-3 py-2 text-sm ring-offset-white placeholder:text-slate-500 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
                                                value={formData.gymRules}
                                                onChange={(e) => handleInputChange(e as any)}
                                                placeholder="Enter gym rules here (e.g. Dress code, equipment use)..."
                                            />
                                            <p className="text-xs text-amber-600 bg-amber-50 p-2 rounded-md font-medium mt-2">🔔 You can edit these terms and rules later anytime from your Dashboard Settings!</p>
                                        </div>

                                        <div className="space-y-4 text-left mt-8 border-t pt-6">
                                            <div className="flex items-center gap-2 mb-2">
                                                <CreditCard className="w-4 h-4 text-primary" />
                                                <Label htmlFor="futurePlanPreference-select" className="font-bold cursor-pointer">Select Preferred Plan After 1-Month Trial</Label>
                                            </div>
                                            <Select
                                                value={formData.futurePlanPreference}
                                                onValueChange={(val) => setFormData(prev => ({ ...prev, futurePlanPreference: val }))}
                                            >
                                                <SelectTrigger id="futurePlanPreference-select" className="bg-white border-2 border-primary/20 focus:border-primary">
                                                    <SelectValue placeholder="Select Plan" />
                                                </SelectTrigger>
                                                <SelectContent>
                                                    <SelectItem value="BASIC">Basic Plan (Single Location)</SelectItem>
                                                    <SelectItem value="PRO">Pro Plan (Multi-location & Advanced Features)</SelectItem>
                                                    <SelectItem value="ENTERPRISE">Enterprise (Custom Setup)</SelectItem>
                                                </SelectContent>
                                            </Select>
                                            <p className="text-[10px] text-slate-500 font-medium italic bg-slate-100 p-2 rounded-lg border border-slate-200">
                                                ✨ Trial Duration: 30 Days. You won't be charged today. We'll use this preference to customize your initial experience and setup.
                                            </p>
                                        </div>
                                        <div className="p-6 bg-slate-50 rounded-xl border-2 border-dashed border-primary/20 mt-8">
                                            <h3 className="font-bold text-primary mb-2">Almost there!</h3>
                                            <p className="text-sm text-slate-600">By clicking finish, you confirm that the provided information is accurate for billing purposes.</p>
                                        </div>
                                    </div>
                                )}
                            </motion.div>
                        </AnimatePresence>
                    </CardContent>

                    <div className="p-6 bg-slate-50 border-t flex justify-between">
                        <Button
                            type="button"
                            variant="ghost"
                            onClick={prevStep}
                            disabled={currentStep === 0 || isSubmitting}
                        >
                            <ArrowLeft className="mr-2 h-4 w-4" /> Back
                        </Button>
                        <Button type="submit" disabled={isSubmitting}>
                            {currentStep === steps.length - 1 ? (
                                isSubmitting ? 'Verifying...' : 'Complete & Verify'
                            ) : (
                                <>Next Step <ArrowRight className="ml-2 h-4 w-4" /></>
                            )}
                        </Button>
                    </div>
                </form>
                <div className="p-4 bg-slate-100/50 border-t flex items-center justify-center gap-2 text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                    <Building2 className="h-3 w-3" />
                    <span>Powered by eMitra Technologies</span>
                </div>
            </Card>
        </div>
    )
}
